    }
    private async Task CambiarRolAsync(string organizacionId, int usuarioId, ChangeEventArgs e)
    {
        string nuevoRol = e.Value?.ToString() ?? "miembro";
        bool actualizado = await DataSvc.ActualizarRolPorOrgYUsuarioAsync(organizacionId, usuarioId, nuevoRol);
        
        if (actualizado)
        {
            mensajeFeedback = $"Se actualizó el rol a {nuevoRol.ToUpper()} con éxito.";
            esError = false;
            await CargarDatosUsuarioAsync();
        }
        else
        {
            mensajeFeedback = "No se pudo actualizar el rol.";
            esError = true;
        }
    }
    private async Task QuitarFotoPerfil()
{
    try
    {
        Console.WriteLine("Intentando eliminar foto.");

        int idActual = 0;
        
        string idStr = await JS.InvokeAsync<string>("localStorage.getItem", "usuario_id");
        if (int.TryParse(idStr, out int parsedId))
        {
            idActual = parsedId;
        }

        if (idActual > 0)
        {
            Console.WriteLine("Enviando solicitud para limpiar foto en Supabase...");
            await DataSvc.EliminarFotoPerfilUsuarioAsync(idActual);
            
            await JS.InvokeVoidAsync("localStorage.removeItem", "usuario_foto");
            
            Console.WriteLine("¡Foto eliminada con éxito!");

            await JS.InvokeVoidAsync("location.reload");

            StateHasChanged();
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error al eliminar la foto: {ex.Message}");
    }
}

    private Dictionary<string, bool> organizacionesExpandidas = new();

    private void AlternarExpandido(string orgId)
    {
        if (organizacionesExpandidas.ContainsKey(orgId))
        {
            organizacionesExpandidas[orgId] = !organizacionesExpandidas[orgId];
        }
        else
        {
            organizacionesExpandidas[orgId] = true;
        }
        StateHasChanged();
    }

